/**
 * A small icon in currentColor, drawn by lucide at an absolute stroke so every
 * glyph in a row shares one weight. `filled` gives a solid glyph, which reads
 * better at 14px and under and inside tinted tiles. These cover basics only:
 * use the product's own icon pack for the rest.
 */
export function Icon({ name, size = 16, stroke = 1.5, filled, className, style }: { name: IconName; size?: number; stroke?: number; filled?: boolean; className?: string; style?: CSSProperties }) {
  const solid = filled ? FILLED[name] : undefined
  const cls = `ss-icon${className ? ` ${className}` : ''}`
  if (!solid && name in LUCIDE) {
    const Glyph = LUCIDE[name as LucideName]
    return <Glyph size={size} strokeWidth={stroke} absoluteStrokeWidth className={cls} style={style} aria-hidden />
  }
  return (
    <svg viewBox="0 0 16 16" width={size} height={size} className={cls} style={style} aria-hidden>
      {solid ? (
        <path d={solid} fill="currentColor" fillRule="evenodd" />
      ) : (
        <path d={DRAWN[name as keyof typeof DRAWN]} fill="none" stroke="currentColor" strokeWidth={stroke} strokeLinecap="round" strokeLinejoin="round" />
      )}
    </svg>
  )
}
